        const joint = new THREE.Vector3(x, y, -.055).applyEuler(surface.rotation).add(surface.position);
        const leg = box(.055, joint.y - .22, .055, metal, x, (joint.y + .22) / 2, joint.z, group);
        leg.name = 'interactive-table-leg';
